\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs28 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 86\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 : Bartholomaeus Brixiensis, Casus Decretorum. \endash  86\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 \endash 93\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 : Historiae super libro Decretorum (siehe zum Inhalt \plain \f1\scaps\lang1033\fs24 Leitschuh\plain \f1\lang1033\fs24 , Kat. I.1, S. 911f.). \endash  93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : leer.}

