\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 100\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bernardus de Montemirato}}\plain \f1\lang1033\fs24  (Abbas Antiquus), {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectura in Decretales Gregorii IX}}\plain \f1\lang1033\fs24 . \endash 100\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 \endash 105\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 : Ders., {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectura in Novellas Constitutiones Innocentii IV.}}\plain \f1\lang1033\fs24  \endash 105\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 \endash 119\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 : Ders., {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Distinctiones}}\plain \f1\lang1033\fs24  (zu den Texten vgl. \plain \f1\scaps\lang1033\fs24 Schulte\plain \f1\lang1033\fs24 , Quellen II, S. 130 und 132; \plain \f1\scaps\lang1033\fs24 Coing\plain \f1\lang1033\fs24 , S. 378; \plain \f1\scaps\lang1033\fs24 Murano \plain \f1\lang1033\fs24 2005, S. 315f., Nr. 247\endash 248)}

