\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 Sammelhandschrift
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Einheit I: Pharetra beatae Mariae virginis \endash  Glossa super regulam S. Benedicti.
\par \pard\fi0\li-540\ql\ri-1605\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Einheit I: 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 36\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pharetra B. Mariae virginis}}\plain \f1\lang1033\fs24 . \endash  37\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 58\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 : Glossa super Regulam S. Benedicti (Incipit und Explicit identisch mit Guilelmus Peraldus, De professione Monachorum. Am Ende Eintrag: \plain \f1\i\lang1033\fs24 Explicit liber petri de Karinthia\plain \f1\lang1033\fs24 ; wenn dies nicht doch der Autor ist, wie bei \plain \f1\scaps\lang1033\fs24 Leitschuh\plain \f1\lang1033\fs24  genannt, k\u246 \'f6nnte es sich um den bisher nicht identifizierbaren Schreiber oder einen Vorbesitzer handeln). Einheit II.: 59\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 90\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Expositio historica veteri testamenti}}\plain \f1\lang1033\fs24  ohne Buchschmuck.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

