\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bamberg}}\plain \f1\lang1033\fs24 ,   {\field{\*\fldinst HYPERLINK "hida://5130[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Benediktinerkloster Michelsberg?}}\plain \f1\lang1033\fs24 ,        {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 2. Viertel 13. Jh.}}}

