\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs28\chcbpat17 Petrus Lombardus}}\plain \f1\b\lang1033\fs28 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs28\chcbpat17 Commentarius in Psalmos}}\plain \f1\b\lang1033\fs28 ; Theodoricus: {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs28\chcbpat17 Medicamentum regenerationis}}\plain \f1\b\lang1033\fs28 ; {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs28\chcbpat17 Alanus ab Insulis}}\plain \f1\b\lang1033\fs28 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs28\chcbpat17 Poenitentiale}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs28 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 : Blatt CXXX des Missale Benedictinum, J. Sensenschmidt, Bamberg 1481.07.31. (GW M24117, BSB-Ink M-421), Pergamentdruck. \endash  1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 79\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 : Petrus Lombardus, Commentarius in Psalmos (Ps 101\endash 150). \endash  79\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 \endash 86\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 : Theodoricus, Theos gratiae \plain \f1\lang1033\fs20 (\u8230 \'85) \plain \f1\lang1033\fs24 dotrix medicamentum regenerationis hoc est: baptismus sive poenitentia, inc.: Devotis in christo sponsalibus theodoricus. \endash  86\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 \endash 94\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 : Alanus ab Insulis, Poenitentiale. \endash Spiegelblatt HD: Blatt eines Evangelistars des 12. Jh. (siehe zum Inhalt vor allem \plain \f1\scaps\lang1033\fs24 Leitschuh\plain \f1\lang1033\fs24 , Kat. I.1, S. 51).}

