\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 49\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : Iustinianus, Institutiones mit Glosse des Accursius (Glossa ordinaria). \endash  50\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 160\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Iustinianus, Authentiken mit Glosse des Accursius (Glossa ordinaria). \endash  160\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 160\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : leer. \endash  161\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 216\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Iustinianus, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Tres Libri (B\u252 \'fccher X\endash XII des Codex)}}\plain \f1\lang1033\fs20  mit Glosse des Hugolinus. \endash  216\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 117\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : alphabetische \u220 \'dcbersicht der Titel der in diesem Band enthaltenen Schriften wohl noch aus dem 13. oder 14. Jh. \endash  217\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Martinus Gosia, Summula de interesse (Siehe zum Inhalt \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.2, S. 517f., \plain \f1\scaps\lang1033\fs20 Dolezalek \plain \f1\lang1033\fs20 1972 ad vocem, \plain \f1\scaps\lang1033\fs20 Conte \plain \f1\lang1033\fs20 1990, S. 126).}

