\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs28\chcbpat17 Graduale Bambergense}}\plain \f1\b\lang1033\fs28 , Fragment
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi540\li-540\ql\ri-2505\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 10\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Graduale vom Osterfest bis \plain \f1\i\lang1033\fs20 zu feria IIII. post pentecostes\plain \f1\lang1033\fs20  (Fragment). \endash  11\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 13\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Kyrie- und Gloriamelodien. \endash  13\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 14\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Antiphonen (\plain \f1\i\lang1033\fs20 in diebus rogationum\plain \f1\lang1033\fs20 ). \endash  14\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 30\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Sequenzen (\plain \f1\i\lang1033\fs20 in Galli cantu\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 ad missam publicam\plain \f1\lang1033\fs20 , dann auf 15\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  zu Stephanus, 15\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  zu Johannes, 16\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 unschuldige Kinder etc., auf  27\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  zur Kirchweihe, auf 28\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  zu Kaiser Heinrich, auf 28\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  zu Kunigunde, Maria etc.). \endash  31\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 32\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Verse zum Offertorium von Stephanus bis 2. Sonntag nach Epiphanie. \endash  32\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 33\plain \f1\super\lang1033\fs20 v-v\plain \f1\lang1033\fs20 : Alleluia und Sequenz sowie Offertorium und Communio zu Fronleichnam. \endash 34\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 42\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : \plain \f1\i\lang1033\fs20 de sancto stephano rege\plain \f1\lang1033\fs20 , Sanctus, Agnus, Offertorien; Hymnus zur hl. Katharina. \endash  43\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 44\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Antiphonen. \endash  44\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 46\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Gloria mit Tropen (\plain \f1\i\lang1033\fs20 de s. stephano\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 de s. Johanne\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 de innocentibus\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 in octava epiphaniae\plain \f1\lang1033\fs20 ). \endash  46\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 50\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : mehrere Kyrie-, Gloria, Sanctus- und Agnusmelodien. \endash  50\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Alleluia-Melodien. \endash  50\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 54\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Alleluiamelodien zu den Festen Dreifaltigkeit, Kunigunde (50\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ). 51\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Sequenz \plain \f1\i\lang1033\fs20 de s. trinitate\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 de s. kunegunde\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 de s. ottone\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 de s. Elyzabet\plain \f1\lang1033\fs20 . \endash  54\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 69\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Offertorienanf\u228 \'e4nge mit Versen. \endash  69\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 71\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Sequenz \plain \f1\i\lang1033\fs20 Lauda Sion\plain \f1\lang1033\fs20  und andere Formulare f\u252 \'fcr Fronleichnam. \endash  71\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 72\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : kaum mehr lesbarer Hymnus zur hl. Barbara \endash  72\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Alleluia und Hymnus auf Kaiser Heinrich. (siehe zum genauen Inhalt \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.2, S. 153f.).}

