\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Teil I: 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : Johannitius, {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Isagoge in medicinam}}\plain \f1\lang1033\fs24 . \endash  13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hippocrates}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber prognosticorum}}\plain \f1\lang1033\fs24 . \endash  21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : Hippocrates: {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De regimine acutorum}}\plain \f1\lang1033\fs24 . \endash  31\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theophilus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De urinis}}\plain \f1\lang1033\fs24 . \endash  39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : Hippocrates, {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber anphorismorum}}\plain \f1\lang1033\fs24 . \endash  49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{