\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 28\plain \f1\super\lang1033\fs24 va\plain \f2\fs24 : Chirurgie des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f2\fs24\chcbpat17 Abu l-Q\u257 \'e2sim Halaf b. cAbb\u257 \'e2s az-Zahr\u257 \'e2w\u299 \'ee}}\plain \f2\fs24  in der \u220 \'dcbersetzung des {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\fs24\chcbpat17 Geradus Cremonsensis}}\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cirurgia Albucasis, de chirurgia libri tres}}\plain \f1\lang1033\fs24 ). \endash  28\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 \endash 33\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ps.-Apuleius Madaurensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Herbarium}}\plain \f1\lang1033\fs24 . \endash  33\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 35\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 : Macrus Floridus ({\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Odo Magdunensis}}\plain \f1\lang1033\fs24 ), {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De viribus herbarum (Excerpta prosaica)}}\plain \f1\lang1033\fs24 . \endash  35\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 \endash 40\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Excerpta medica (Antidotarium?)}}\plain \f1\lang1033\fs24 . \endash  40\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 \endash 43\plain \f1\super\lang1033\fs24 rc\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Glossarium medicum}}\plain \f1\lang1033\fs24 . \endash  43\plain \f1\super\lang1033\fs24 rd\plain \f1\lang1033\fs24 \endash 43\plain \f1\super\lang1033\fs24 vd\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tractatus Quid pro quo}}\plain \f1\lang1033\fs24 . (Siehe zum Inhalt \plain \f1\scaps\lang1033\fs24 Leitschuh \plain \f1\lang1033\fs24 Kat. I.2, 537\endash 539, \plain \f1\scaps\lang1033\fs24 Sudhoff\plain \f1\lang1033\fs24 , 1918, S. 20ff. und Ausst. Kat. Ex Oriente Lux, S. 432f. (Kat. Nr. X 5 \endash  \plain \f1\scaps\lang1033\fs24 Detlev Quintern\plain \f1\lang1033\fs24 ))}

