\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Zu Beginn der einzelnen Kapitel vierzeilige {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Deckfarbeninitialen}}\plain \f1\lang1033\fs24  (1,5 cm hoch) einer Hand mit einfachen Akanthusblatt-Ausl\u228 \'e4ufern (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 1\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 3\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 11\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 12\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 12\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 34\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 34\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 35\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 36\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 37\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 38\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 39\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 42\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 43\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 47\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 47\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 48\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 49\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 49\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 50\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 51\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 52\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 53\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 53\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 53\plain \f1\super\lang1033\fs24 vb