\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Register zu den beiden folgenden Texten. \endash  1a\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 270\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Guilelmus Durantis}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Speculum iudiciale}}\plain \f1\lang1033\fs20 . \endash  271\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 324\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 : ders., {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Repertorium juris}}\plain \f1\lang1033\fs20 . \endash  324\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : alphabetischer Index \u252 \'fcber die Titel des Speculum}

