\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 164\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Iohannes de Friburgo}}\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Summa confessorum}}\plain \f1\lang1033\fs20 . \endash  164\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 169\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 : Iohannes de Friburgo: {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Confessionale seu Manuale confessorum}}\plain \f1\lang1033\fs20 . \endash  169\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : oben: {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 arbor consanguinitatis}}\plain \f1\lang1033\fs20 , unten: {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 arbor affinitatis}}\plain \f1\lang1033\fs20 , darunter weitere Schema zum Verwandschaftsgrad (Abb. 662; siehe zum Inhalt der Handschrift \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.1, S. 617f. und \plain \f1\scaps\lang1033\fs20 Murano \plain \f1\lang1033\fs20 2005, S. 606 und 608)}

