\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : leer (nur Buchtitel in schwarzer Tinte von einer Hand wohl des 18./19. Jh.). \endash  1\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 129\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Maria Magdalena-Buch}}\plain \f1\lang1033\fs20 . \endash  129\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 156\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Vita und Legenden zur hl. Martha}}\plain \f1\lang1033\fs20 . \endash  156\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 167\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Vita und Legenden zum hl. Lazarus}}\plain \f1\lang1033\fs20 . \endash  167\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 \endash 174\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 : Gebete zu Maria Magdalena, Maria, Martha und Lazarus. \endash  174\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : leer. \endash  175\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 184\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Auferstehungsgeschichte in sechs Kapiteln. \endash  184\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 186\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : Lectio und Omelia eiusdem beati Gregorii pape (siehe zum Inhalt \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat.I.2, S. 258\endash 260)}

