\par \pard\fi0\li0\ql\ri-2505\sb0\sa0\itap0 Z.T. aufw\u228 \'e4ndigere braune {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cadellen}}\plain \f1\lang1033\fs24  mit roter Strichelung, Kopfstempelformen, ausgesparten Vierp\u228 \'e4ssen und unprofessionellem rotem Fleuronn\u232 \'e8e.}

