\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : leer. \endash  1\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 208\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Petrus Lombardus}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Sententiarum libri IV}}\plain \f1\lang1033\fs20 , davon 1\plain \f1\super\lang1033\fs20 va-b\plain \f1\lang1033\fs20 : Proemium, 2\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 3\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 : Capitula. \endash  2\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 208\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 : Petrus Lombardus, sententiarum libri IV. (121\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 121\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : leer). \endash  208\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : leer.}

