\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannes Bassianus}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Arbor actionum}}\plain \f1\lang1033\fs20  (Ed. siehe \plain \f1\scaps\lang1033\fs20 L. Fowler-Magerl \plain \f1\lang1033\fs20 1984, S. 177f.), Redaktion A (siehe \plain \f1\scaps\lang1033\fs20 Errera \plain \f1\lang1033\fs20 1995, S. 351, Anm. 147) \endash  3\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 82\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : Authenticum mit Glosse. \endash  83\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 132\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Tres libri mit Glosse}}\plain \f1\lang1033\fs20 . \endash  133\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Titelrubriken der Collationes und zu den Tres Libri in vier Spalten, darunter zweimaliges Sanctus mit Neumen. \endash  133\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Schemata \u252 \'fcber Verwandtschaftsgrade, darunter ein Rezept (vgl. zum Inhalt \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.2, S. 537f., zum ungew\u246 \'f6hnlichen Schema der Deszendenz und der Nachkommen von frater und soror: \plain \f1\scaps\lang1033\fs20 Schadt 1982\plain \f1\lang1033\fs20 , S. 287f.)}

