\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Ornamentale {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Die zweifarbigen, blau-rot gespaltenen Initialen mit Punktverdickung und Fleuronn\u233 \'e9e stammen von einer Hand und finden sich auf 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 66\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 120\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 150\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 160\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 und 191\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . Sie sind f\u252 \'fcnf- bis zw\u246 \'f6lfzeilig (die f\u252 \'fcnfzeiligen ca. 3,0 x 2,3 cm, die zw\u246 \'f6lfeilige auf 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 : 6,3 x 5,7 cm) und zeigen Schaftaussparungen in Form von Kopfstempeln, Bl\u228 \'e4ttern, Bl\u252 \'fcten, Kreuzblumen, Pflanzen- und Phantasietieren, meist Drachen. Das Fleuronn\u233 \'e9e ist ebenfalls in Blau und Rot}

