\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Deckfarbeninitiale
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 34\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : (D)\plain \f1\i\lang1033\fs24 a alle die frawen die bei Sant Claren lebten \plain \f1\lang1033\fs24 (\u8230 \'85). Unprofessionelle blaue {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Deckfarbeninitiale}}\plain \f1\lang1033\fs24  mit Punktverdickung und quadratischen Schaftaussparungen auf Goldgrund (4,7 x 4,5 cm \endash  Abb. 162) mit blauem, randbegleitendem Fleuronn\u233 \'e9e}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

