\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs28 Astronomische Sammelhandschrift
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 8\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannes de Sacro Bosco}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Algorismus sive Arithmetica}}\plain \f1\lang1033\fs20  [Tractus de Algorismo]. \endash  9\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Zahlentafel und tabellarische \u220 \'dcbersicht der beweglichen Feste von 1353\endash 1382 (siehe hierzu \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.2, S. 482). \endash  9\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 27\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : ders.: {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Computus ecclesiasticus}}\plain \f1\lang1033\fs20 . \endash  28\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 40\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : ders.: {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Liber de Sphaera}}\plain \f1\lang1033\fs20 . \endash  40\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Tabula terminorum (f\u252 \'fcr die beweglichen Feste), 41\plain \f1\super\lang1033\fs20 r\endash v\plain \f1\lang1033\fs20 : tabula Guerlandi (Johannes de Garlandia), ebenfalls f\u252 \'fcr die beweglichen Feste. \endash  42\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 : Erkl\u228 \'e4rung der Tabula von verschiedenen H\u228 \'e4nden. \endash  43\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 53\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Johannes {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannes Anglicus von Montpellier}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Tractus Quadrantis}}\plain \f1\lang1033\fs20  (Edition \plain \f1\scaps\lang1033\fs20 Nan Long Britt \plain \f1\lang1033\fs20 1956, S. VII. und 22f., Msc.Astr.1 [dort unter Math. 1] als Sigle I), \plain \f1\scaps\lang1033\fs20 Nan L. Hahn\plain \f1\lang1033\fs20 , 1982, S. 3, Sigle I. \endash  53\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 54\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 De Compositione Quadrantis}}\plain \f1\lang1033\fs20 . \endash  55\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 : zwei Schemata (siehe Ausstattung). \endash  56\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 64\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Alexander de Villa Dei}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Massa Computi}}\plain \f1\lang1033\fs20 . \endash  65\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 94\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Tractus grammaticus}}\plain \f1\lang1033\fs20 . \endash  94\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 101\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Quaestiones Mathaei de Bononia de modis significandi et grammatica}}\plain \f1\lang1033\fs20  (siehe zum Inhalt \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.2, S. 482\endash 484)}

