\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 142\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Quinque compilationes antiquae}}\plain \f1\lang1033\fs20  (Compilatio I und II mit den Glossen Tancreds). \endash  143\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 159\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Alanus ab Insulis}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 De poenitentia libri IV.}}\plain \f1\lang1033\fs20   \endash  159\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 160\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bernardus Balbi von Pavia}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Tractatus de impedimentis matrimonii}}\plain \f1\lang1033\fs20 . \endash  160\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 162\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : Sermo und Anf\u228 \'e4nge eines Glossars? (vgl. \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat.I.1, S. 892)}

