\pard\sl254\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Ausstattung
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Zahlreiche Fleuronn\u233 \'e9e-Initialen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zu Beginn und zu den Tituli des Ordo iudiciarius und der Summa curialis zahlreiche zwei- bis dreizeilige (Ausnahme: 5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  14-zeilig, 5 cm hoch \endash  Abb. 392), blau-rot alternierende {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lombarden}}\plain \f1\lang1033\fs24  mit Knospenfleuronn\u233 \'e9e in der Gegenfarbe (ca. 1 cm hoch). 5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  geteilter Buchstabenk\u246 \'f6rper mit ausgespartem Kopfstempel. Entlang den Textspalten zwei- bis vierbahniges kurzes Fadenwerk mit geraden Endungen. Im Besatz einzelne Perlen oder kleine Perlengruppen mit Kernen und kurz gewellte Fibrillen. Blatt 37\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  vom Buchstabenk\u246 \'f6rper ausgehend ein Fleuronn\u233 \'e9e-Stab entlang der Textspalte einseitig besetzt mit blau-rot alternierenden Keilformen. Einzelne Perlen und Fleuronn\u233 \'e9e-Stab besetzt mit kurzen Fadenh\u228 \'e4kchen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Die Fleuronn\u233 \'e9eausstattung der Handschrift stammt von einer Hand. Die reduzierten, vereinfachten Elemente, wie u.a. das kurze Fadenwerk und die vereinzelten Perlen bzw. Perlengruppen legen eine Datierung in das 4. Viertel des 13. Jh. nahe (vgl. \plain \f1\scaps\lang1033\fs24 Stirnemann \plain \f1\lang1033\fs24 1990, Kat. Nr. 44\endash 46, S. 71; 1285\endash 1288). Die im Kolophon der Handschrift festgehaltene Datierung des letzten Textes (Summa curialis) auf das Jahr 1285 (s.o.) liefert einen Terminus post quem. Eine Entstehung der Handschrift in Paris erscheint durchaus m\u246 \'f6glich.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

