\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Ausstattung
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Zahlreiche Fleuronn\u233 \'e9e-Initialen, 1 ornamentale Deckfarbeninitiale mit anschlie\u223 \'dfender Drolerie.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zu den Tituli und hervorgehobenen Abs\u228 \'e4tzen kleine zweizeilige (1,0 cm hoch), zu Buch II\endash V gr\u246 \'f6\u223 \'dfere zwei- bis vierzeilige blau-rot alternierende Lombarden (1,0\endash 1,8 cm) mit Fleuronn\u233 \'e9e in der Gegenfarbe (Abb. 409). Die gr\u246 \'f6\u223 \'dferen blau-rot gespaltenen Buchstabenk\u246 \'f6rper mit ausgesparten Segmentb\u246 \'f6gen und Kopfstempeln. In den Binnenfl\u228 \'e4chen Knospenfleuronn\u233 \'e9e mit Bl\u252 \'fcteneinschl\u252 \'fcssen. Im Besatz Perlen mit Kernen, kurze Punktreihen, lange Fibrillen, Dreipunktmotive und kleine Bl\u252 \'fcten. 2\endash 3-lagige, parallel verlaufende Fadenausl\u228 \'e4ufer entlang den Textspalten.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Ornamentale Deckfarbeninitiale und Drolerie
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Zu Beginn von Buch I eine {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ornamentale Deckfarbeninitiale}}\plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \endash  Abb. 408). Altrosa Buchstabenk\u246 \'f6rper vor blauem Grund mit ornamentalem Deckwei\u223 \'dfauftrag. In der Binnenfl\u228 \'e4che Dornblattranken auf Goldgrund.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Ausgehend vom Initialschaft, entlang der inneren Textspalte und auf Kopf- und Fu\u223 \'dfsteg, zwei- bzw. einfarbige (oben) Leisten (Leiste innen mit kleinen Schlaufen). Enden und Gelenkstellen mit Dornenbesatz und kurzen Rankenausl\u228 \'e4ufern. Als Endmotive Dornbl\u228 \'e4tter. Auf der unteren Leiste eine Jagdszene mit Hund und Hase.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Text, Fleuronn\u233 \'e9e und Deckfarbemalerei sind im Stil identisch mit {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Can.93}}\plain \f1\lang1033\fs24  (Kat. Nr. 129) und weisen auf eine Entstehung in Paris (bzw. in einem Ort, in dem Pariser Werke qualit\u228 \'e4tvoll nachgeahmt wurden) und eine Entstehung um 1310\endash 1320.}

