\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs28 Gregorius IX. Papa, Liber extra mit Glossa ordinaria
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 4\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Register. \endash  5\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 336\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Liber Extra}}\plain \f1\lang1033\fs20  (Decretales {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gregorii IX. papae}}\plain \f1\lang1033\fs20 ) cum Glossa ordinaria {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bernardi de Botone Parmensis}}\plain \f1\lang1033\fs20 . Marginalglossen, u. a. Texte von {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannes Andreae}}\plain \f1\lang1033\fs20  (vgl. \plain \f1\scaps\lang1033\fs20 Leitschuh\plain \f1\lang1033\fs20 , Kat. I.1, S. 898f.; zum Liber Extra vgl. Ausst. Kat. \plain \f1\scaps\lang1033\fs20 Glaube und Wissen\plain \f1\lang1033\fs20 , Kat. Nr. 57, 58; \plain \f1\scaps\lang1033\fs20 Bertram 2002\plain \f1\lang1033\fs20 ).}

