\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Prolog: \plain \f1\i\lang1033\fs20 Nota quod lector\plain \f1\lang1033\fs20 . \endash  1\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 2\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 :Prologi et Tituli. \endash  3\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 392\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Summa confessorum}}\plain \f1\lang1033\fs20 . \endash  392\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 \endash 407\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Statuta ex sexto decretalium addita}}\plain \f1\lang1033\fs20 . \endash  408\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 462\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Tabula. \endash  462\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 462\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : leer. }

