\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 64\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannis Andreae}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hieronymianus}}\plain \f1\lang1033\fs20 . \endash 65\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 119\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hieronymus}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Epistolae et Dialogus adversus Pelagianos}}\plain \f1\lang1033\fs20 . \endash Textliche \u220 \'dcbereinstimmung, einschlie\u223 \'dflich der Randbemerkungen, zu der Handschrift {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Msc.Patr.80}}\plain \f1\lang1033\fs20 , die als Vorlage diente (vgl. \plain \f1\scaps\lang1033\fs20 Miekisch \plain \f1\lang1033\fs20 1989, S. 9)}

