\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zu den Kapiteln 2 (7\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) und 3 (19\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) des Hieronymianus f\u252 \'fcnfzeilige rote Lombarden (2,7\endash 3,0 cm hoch) mit violettem bzw. violettem und braunem Perl- und Knospenfleuronn\u233 \'e9e, das von 2. Hand von {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Bibl.9(1\endash 3}}\plain \f1\lang1033\fs24  (Kat. Nr. 43) und der von {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Patr. 91}}\plain \f1\lang1033\fs24  (Kat. Nr. 44) stammt. Auf 74\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 dreizeilige rote Lombarde mit einfachem braunem Fleuronn\u233 \'e9e (Konglomerat aus gekernten Knospen im Binnenfeld, als Besatz Konturbegleitlinien mit gliedernden Perlpyramiden)}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;}

\uc1
\pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Ornamentale Deckfarbeninitiale
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Auf 22\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 19zeilige blau rot in Kopfstempfelformen gespaltene {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ornamentale Deckfarbeninitiale}}\plain \f1\lang1033\fs24  (11,7 cm hoch \endash Abb. 197) mit Fleuronn\u233 \'e9ebesatz in roter, brauner und gr\u252 \'fcner Tinte. Die Binnenfl\u228 \'e4che aus braun, gelb gr\u252 \'fcn und violett kolorierten Palmetten}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Historisierte Fleuronn\u233 \'e9e-Initiale}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zum Prolog des Hieronymianus eine historisierte Initiale mit kolorierter Federzeichnung in der Binnenfl\u228 \'e4che. Das rot-lila kombinierte Fleuronn\u233 \'e9e wie bei den restlichen Fleuronn\u233 \'e9e-Initialen (s.o.). 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 1\plain \f1\super\lang1033\fs24 ra \plain \f1\lang1033\fs24 (Prolog zum Hieronymianus, Kapitel 1) (H)\plain \f1\i\lang1033\fs24 oc opus\plain \f1\lang1033\fs24 . Dreizehnzeilige Initiale. Hieronymus, nimbiert, als Kardinal am Schreibpult sitzend. Im oberen Bildfeld ein unbeschriebenes Schriftband. 7,5 x 5,2 cm. \plain \f1\b\lang1033\fs24 Abb. 196
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Ausgespart aus dem Buchstabenk\u246 \'f6rper ein anthropokephales Fabelwesen mit schlaufenf\u246 \'f6rmigem Hals. Im Besatz Knospenfleuronn\u233 \'e9e mit einbeschriebener Bl\u252 \'fcte und Ausl\u228 \'e4ufern entlang der Textspalte (Fleuronn\u233 \'e9e-Details vgl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Bibl.9(1\endash 3}}\plain \f1\lang1033\fs24 , 2. Hand (Kat. Nr. 43) und {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Patr.70}}\plain \f1\lang1033\fs24  (Kat. Nr. 44)}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Verantwortlich f\u252 \'fcr die einheitliche Fleuronn\u233 \'e9e-Ausstattung ist der ebenfalls in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Bibl.9(1\endash 3}}\plain \f1\lang1033\fs24  (2. Hand; Kat. Nr. 43) und {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Patr.70}}\plain \f1\lang1033\fs24  (Kat. Nr. 44) nachweisbare K\u252 \'fcnstler. Bei gleichem Ornamentrepertoire zeigt die Umsetzung im Fleuronn\u233 \'e9e Fortschritte, wie z. B. die hier bereits geleistete direkte Integration der Profilgesichter in den Fleuronn\u233 \'e9e-Besatz. Die etwas fr\u252 \'fchere Variante (aufgesetzte Profilgesichter) zeigt Msc.Patr.70 (Kat. Nr. 44 \endash  Abb. 193)}

