\pard\sl254\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Fleuronn\u233 \'e9e-Initialen
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Die vier- bis 14zeiligen blauen {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24  (2,7\endash 8,7 cm hoch, auf 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 8\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 10\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 15\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 24\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 , 30\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 35\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 39\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 57\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 61\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ), nur auf 1\plain \f1\super\lang1033\fs24 ra \plain \f1\lang1033\fs24 mit ausgesparten kolorierten Mischwesen, zeigen einheitliche rote Fleuronn\u233 \'e9e-Ausstattung von der auch der Besatz der Deckfarbeninitialen stammt.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 In den Binnenfl\u228 \'e4chen und im Besatz Knospenfleuronn\u233 \'e9e mit Ausl\u228 \'e4ufern entlang den Textspalten (im Detail vgl. 2. Hand der Neunkirchener Bibel {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Bibl.9(1\endash 3}}\plain \f1\lang1033\fs24 , Kat. Nr. 43; insbesondere Bd. 1, 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). In den Binnenfl\u228 \'e4chen in das Fleuronn\u233 \'e9e einbeschriebene, kolorierte Bl\u252 \'fctenmedaillons (29\plain \f1\super\lang1033\fs24 va \plain \f1\lang1033\fs24 \endash  Abb. 193, 57\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , 61\plain \f1\super\lang1033\fs24 va \plain \f1\lang1033\fs24 [nur in Vorzeichnung]). H\u228 \'e4ufige Verwendung von an die Fadenausl\u228 \'e4ufer angesetzten Profilgesichtern (gelegentlich mit herausgestreckter Zunge)}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

