\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 3\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Kalender. \endash  Blatt 4: \plain \f1\i\lang1033\fs20 Domine labia mea aperies\plain \f1\lang1033\fs20 ,im Anschluss Ps 94. \endash  4\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 208\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Psalterium}}\plain \f1\lang1033\fs20 . \endash  208\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 214\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Antiphonen und Orationen: \plain \f1\i\lang1033\fs20 Von dem heiligen Geiste\plain \f1\lang1033\fs20 bis \plain \f1\i\lang1033\fs20 Von allen Heiligen\plain \f1\lang1033\fs20 . \endash  214\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 217\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 :Completorium. \plain \f1\i\lang1033\fs20 \endash  \plain \f1\lang1033\fs20 217\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 232\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Orationen: \plain \f1\i\lang1033\fs20 Sunnin tac von der zu kunft ihesu christi \plain \f1\lang1033\fs20 bis \plain \f1\i\lang1033\fs20 Von sante Thoma\plain \f1\lang1033\fs20 . \endash  232\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Ps 142.}

