\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zahlreiche Fleuronn\u233 \'e9e-Initialen, 4 ornamentale Initialen, 2 historisierte Initialen. \endash 129\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 und 130\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Raum f\u252 \'fcr nicht ausgef\u252 \'fchrte Arbores (zu den Arbores bei Goffredus de Trano vgl. \plain \f1\scaps\lang1033\fs24 Schadt \plain \f1\lang1033\fs24 1982, S. 212\endash 213; s. auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Can.48}}\plain \f1\lang1033\fs24 )}

