\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Vorrede zum Psalter (Nachtrag Langheim, 16. Jh.). \endash  1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Inhaltsverzeichnis (Nachtrag). \endash  2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 161\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Psalterium}}\plain \f1\lang1033\fs20 . \endash  161\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 176\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 :Cantica. \endash 176\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : 2 Gebete. \endash  176\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 177\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Litanei. \endash  178\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 182\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Gebete. \endash  182\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 187\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Cursus sanctae Marie virginis (Bll. 185\endash 186 unbeschrieben). \endash  189\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 191\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Gebete aus dem Brevier und Hymnen (u.a. von einer Hand des 16. Jh.)}

