\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Bd. 1: I\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Titel und Besitzvermerk von J. Graff. \endash 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Inhaltsangabe. \endash 2\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 389\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : B\u252 \'fccher mit Prologen in der Reihenfolge: 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 285\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Gn\endash III Esr. \endash 286\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 300\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Iob. \endash 300\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 305\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Tb. \endash 306\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 313\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Est. \endash 313\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 320\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Idt. \endash 320\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 353\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : I Mcc u. II Mcc. \endash 354\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 389\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 : Ps. Prologe. \endash 389\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 \endash 389\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : leer. \endash 390\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 429\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : \plain \f1\i\lang1033\fs20 Interpretationes Hebraicorum et Latinorum nominum per ordinem alphabeticum\plain \f1\lang1033\fs20 . \endash 430\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 434\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : \plain \f1\i\lang1033\fs20 Interpretationes nominum latinorum secundum libros totius biblie\plain \f1\lang1033\fs20 . \endash Bd. 2: I\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : Titel und Besitzvermerk von J. Graff. \endash 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Inhaltsangabe. \endash 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 218\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 : B\u252 \'fccher in der gew\u246 \'f6hnlichen Reihenfolge: 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 218\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Prv\endash Mal. \endash 218\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 \endash 220\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Prologe zu Mt. \endash 221\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 224\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : Canones. \endash 224\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 226\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : Capitula zu Mt. \endash 226\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 \endash 404\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 : Mt\endash Apc. \endash 404\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : leer. Am Seitenrand in Bd. 2, 227\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 \endash 306\plain \f1\super\lang1033\fs20 v \plain \f1\lang1033\fs20 Eintrag der Evangelienkonkordanzen zu Mt\endash Io in brauner Tinte.}

