\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Eine schmale braune Cadelle. Eine Fleuronn\u233 \'e9e-Lombarde.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Lombarde}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Die zweizeilige rote Lombarde (1,0 cm hoch) zeigt gr\u252 \'fcnes Knospenfleuronn\u233 \'e9e mit roter Kernung. Als Binnenformen dominieren herzf\u246 \'f6rmig angelegte eingerollte Knospen an langen Stielen und Zwischenknospen. Als Besatz \endash  auf der R\u252 \'fcckseite finden sich Reste von 2 weiteren Lombarden mit rotem und gr\u252 \'fcnem Besatzfleuronn\u233 \'e9e derselben Hand \endash , dienen konturbegleitende Linien. In den Zwickeln v-f\u246 \'f6rmig angeordnete gekernte Knospen an langen Stielen sowie tropfenf\u246 \'f6rmige gekernte Schlaufen. Links ist ein partiell von gekernten Perlreihen gerahmter Fleuronn\u233 \'e9e-Stab angesetzt, der oben in einem blasenf\u246 \'f6rmigen Ende ausl\u228 \'e4uft, w\u228 \'e4hrend die einzelnen F\u228 \'e4den nach unten hin streuen und durch eine mittig platzierte Halbpalmette geschlossen werden.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Die Fleuronn\u233 \'e9e-Formen mit den v-f\u246 \'f6rmig angeordneten Knospen an langen Stielen, die oft herzartige Formen bilden, finden sich vergleichbar vor allem in Handschriften der 1. H\u228 \'e4lfte des 14. Jh., etwa in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lat. qu. 792}}\plain \f1\lang1033\fs24  auf fol. 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  der Staatsbibliothek zu Berlin (\plain \f1\scaps\lang1033\fs24 V\plain \f1\scaps\lang1033\fs24 \u228 \'e4\plain \f1\scaps\lang1033\fs24 th \plain \f1\lang1033\fs24 2001, Kat. Nr. 17 mit Abb. 43), Erfurt, 2. Viertel 13. Jh.; auch die Schlaufen am Besatz lassen sich vor allem in diesem Zeitraum mehrfach nachweisen, so in einer um 1350 datierten, ebenso nach Erfurt lokalisierten Handschrift der Staatsbibliothek zu Berlin, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lat. fol. 856}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 V\plain \f1\scaps\lang1033\fs24 \u228 \'e4\plain \f1\scaps\lang1033\fs24 th \plain \f1\lang1033\fs24 2001, Kat. Nr. 16, Abb. 42). Doch finden sich vergleichbare Binnenstrukturen der Initialen auch in Regensburger Handschriften, z.B. in {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 14003}}\plain \f1\lang1033\fs24  der BSB M\u252 \'fcnchen (\plain \f1\scaps\lang1033\fs24 Hernad \plain \f1\lang1033\fs24 2000, Kat. Nr. 18, mit Abb. 53), um 1310/20. Das Bamberger Fragment wird man in das 2. Viertel des 14. Jh. datieren und nach Westdeutschland oder Mitteldeutschland geben k\u246 \'f6nnen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

