\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1 Fleuronn\u233 \'e9elombard
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Eine blaue {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9elombarde}}\plain \f1\lang1033\fs24  (1,8 cm hoch) mit rotem {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Palmetten-Fleuronn\u233 \'e9e}}}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Das relativ einfache Fleuronn\u233 \'e9e aus Palmetten, Spiral-, Kreisformen und eingerollten Fadenausl\u228 \'e4ufern weist ebenso wie die Schrift auf eine Entstehung in Oberitalien. Vergleichbar sind etwa die Formen in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 14620}}\plain \f1\lang1033\fs24 , in der 2. H\u228 \'e4lfte des 13. Jh. in Genua entstanden (\plain \f1\scaps\lang1033\fs24 Bauer-Eberhardt \plain \f1\lang1033\fs24 2011, Kat. Nr. 73 mit Abb. 36), oder {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 3893}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Bauer-Eberhardt \plain \f1\lang1033\fs24 2011, Kat. Nr. 100 mit Abb. 57), in der Emilia, wohl in Bologna, im 3. Viertel des 13. Jh. ausgestattet. Hier wie dort finden sich neben den Palmetten- und Halbpalmetten auch vergleichbare Fadenausl\u228 \'e4ufer.}

