\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Drei Lombarden mit Palmettenfleuronn\u233 \'e9e.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Drei zwei- bis vierzeilige rote {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lombarden}}\plain \f1\lang1033\fs24  (1,5\endash 2,0 cm hoch, z.T. mit geraden Schaftausparungen, z.T. mit rot gepunktetem Schaft) mit rotem und braunem {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Palmetten-Fleuronn\u233 \'e9e}}\plain \f1\lang1033\fs24 .
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 Fleuronn\u233 \'e9e
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Als Binnenschmuck der Lombarden dienen eingerollte Knospen, z.T. mit Drei-Perlen-Motiv und Palmetten, teils mit gekernten Perlen angereichert. Der Besatz besteht ebenfalls aus Palmetten und Halbpalmetten, die z.T. gr\u246 \'f6\u223 \'dfer sind und in den Bogungen des Blattrandes Punkte integrieren.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Die gro\u223 \'dfen Halbpalmetten mit den Punkten im gebogten Rand verweisen auf die Verarbeitung \u228 \'e4lterer Quellen aus der 1. H\u228 \'e4lfte des 13. Jh. Sie finden sich z.B. in den ansonsten allerdings v\u246 \'f6llig anders angelegten Rankeninitialen etwa des {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 29306}}\plain \f1\lang1033\fs24  der BSB M\u252 \'fcnchen (\plain \f1\scaps\lang1033\fs24 Klemm\plain \f1\lang1033\fs24 1998, Kat. Nr. 9 mit Abb. 21), Sch\u228 \'e4ftlarn, 1. Drittel 13. Jh., in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 7950}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Klemm \plain \f1\lang1033\fs24 1998, Kat. Nr. 129 mit Abb. 378), Kaisheim, 2. Viertel bis Mitte 13. Jh., aber auch noch in {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cgm 7878}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Klemm \plain \f1\lang1033\fs24 1998, Kat. Nr. 33 mit Abb. 107), Umkreis Tegernsee, nach 1295, oder in {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 5195}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Klemm \plain \f1\lang1033\fs24 1998, Kat. Nr. 58 mit Abb. 58), vermutlich Oberaltaich, Ende 13. Jh.; die s-f\u246 \'f6rmigen Einrollungen mit Knospen im Zentrum zeigt \u228 \'e4hnlich {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 29308}}\plain \f1\lang1033\fs24  der BSB M\u252 \'fcnchen (\plain \f1\scaps\lang1033\fs24 Klemm \plain \f1\lang1033\fs24 1998, Kat. Nr. 172 mit Abb. 465), Benediktbeuern, Ende 13./Anfang 14. Jh.; das Drei-Perlen-Motiv findet sich wie z.T. auch vergleichbare Palmettenanordnungen auch in der vor 1297 datierbaren in N\u252 \'fcrnberg ausgestatteten Handschrift {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc.Lit.99}}\plain \f1\lang1033\fs24  (Kat. Nr. 25). Das Fragment wird in S\u252 \'fcddeutschland am Ende des 13. Jh. entstanden sein.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

