\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Antiphonarfragmente}}\plain \f1\lang1033\fs20 : Ges\u228 \'e4nge f\u252 \'fcr die Feste des hl. Tiburtius, Geburt Mariae, Himmelfahrt Mariae, Augustinus und Enthauptung Johannes des T\u228 \'e4ufers, Kirchweihe etc.}

