\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 Henricus de Segusia, Lectura in decretales Gregorii IX.; Lectura in novellas constitutiones Innocentii IV. (4 B\u228 \'e4nde)
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Inhalt
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Bd. 1, 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash  Bd. 4, 271\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Henricus de Segusia}}\plain \f1\lang1033\fs20  (Hostiensis), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Lectura in Decretales Gregorii IX.}}\plain \f1\lang1033\fs20  \endash Bd. 4, 272\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 \endash 325\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 : ders., {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Lectura in Novellas Constitutiones Innocentii IV.}}\plain \f1\lang1033\fs20  (Zum Text vgl. \plain \f1\scaps\lang1033\fs20 Coing 1973\plain \f1\lang1033\fs20 , S. 378. \endash  \plain \f1\scaps\lang1033\fs20 Rous\plain \f1\scaps\lang1033\fs20 e, \plain \f1\scaps\lang1033\fs20 Rouse \plain \f1\lang1033\fs20 2000, Bd. 2, S. 138. \endash  \plain \f1\scaps\lang1033\fs20 Murano \plain \f1\lang1033\fs20 2006, S. 75, Anm. 117 und S. 519, Nr. 475, S. 525, Nr. 478).}

